"""Classify region-gene pairs; input tables are generated by script 00.
Denominator: all AS-testable pairs matched to finite gene log2FC and padj.
DAS: any event with FDR < 0.05 and |delta PSI| >= 0.05.
DEG: gene padj < 0.05 and |log2FC| > 0.5.
Scatter y: maximum |delta PSI| across ALL testable events.
"""
from pathlib import Path
import numpy as np
import pandas as pd
# Parameters
OUT = Path(__file__).resolve().parent / "results"
AS_FDR = 0.05
DPSI_THRESH = 0.05
GENE_PADJ = 0.05
GENE_FC = 0.5
OUT.mkdir(parents=True, exist_ok=True)
KEY=['comparison','region','gene_name']
e=pd.read_csv(OUT/'AS_testable_events_read10.tsv.gz',sep='\t')
m=pd.read_csv(OUT/'gene_results.tsv.gz',sep='\t',low_memory=False)
e['DAS_event']=e.FDR_num.lt(AS_FDR)&e.abs_dPSI.ge(DPSI_THRESH)
e['sig_abs']=e.abs_dPSI.where(e.DAS_event)
p=e.groupby(KEY,as_index=False).agg(n_testable=('EventID','nunique'),n_DAS=('DAS_event','sum'),max_abs_dPSI=('abs_dPSI','max'),max_abs_dPSI_sig=('sig_abs','max'),min_AS_FDR=('FDR_num','min'))
p=p.merge(m[KEY+['gene_id','log2FC','padj']],on=KEY,how='left',validate='one_to_one',indicator=True)
p['plottable']=p['_merge'].eq('both')&np.isfinite(p.log2FC)&np.isfinite(p.padj)
p.drop(columns='_merge').to_csv(OUT/'all_AS_gene_merge_audit.tsv.gz',sep='\t',index=False)
p=p[p.plottable].drop(columns='_merge').copy()
p['DAS']=p.n_DAS.gt(0)
p['DEG']=p.padj.lt(GENE_PADJ)&p.log2FC.abs().gt(GENE_FC)
p['panel_class']=np.select([p.DAS&p.DEG,p.DAS,p.DEG],['both','DAS only','DEGs only'],default='neither')
# 所有点统一显示可检测事件最大幅度，显著性独立由DAS字段判定
p['plot_y']=p.max_abs_dPSI
p['in_focus']=p.log2FC.between(-2.5,2.5)
p.to_csv(OUT/'four_class_points.tsv.gz',sep='\t',index=False)
rows=[]
for comp,x in p.groupby('comparison'):
 for region in ['ALL']+sorted(x.region.unique()):
  d=x if region=='ALL' else x[x.region.eq(region)]
  for cls in ['DAS only','DEGs only','both','neither']:
   z=d[d.panel_class.eq(cls)]
   rows.append(dict(comparison=comp,region=region,category=cls,n_region_gene=len(z),n_unique_genes=z.gene_name.nunique(),n_in_focus=int(z.in_focus.sum()),total=len(d),percent=100*len(z)/len(d)))
s=pd.DataFrame(rows);s.to_csv(OUT/'four_class_counts.tsv',sep='\t',index=False)
assert not p.duplicated(KEY).any()
assert s.groupby(['comparison','region']).percent.sum().sub(100).abs().lt(1e-8).all()
print(s[s.region.eq('ALL')].to_string(index=False))
print('DAS false but y>=0.05:',p[~p.DAS&p.plot_y.ge(.05)].groupby('comparison').size().to_dict())
